<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('admins.edit');$roleId=filter_var(input('role_id'),FILTER_VALIDATE_INT);if(!$roleId){http_response_code(404);exit('Not found');}$stmt=db()->prepare('SELECT * FROM admin_roles WHERE id=?');$stmt->execute([$roleId]);$role=$stmt->fetch();if(!$role){http_response_code(404);exit('Not found');}$permissions=db()->query('SELECT * FROM admin_permissions ORDER BY code')->fetchAll();if(is_post()){verify_csrf();if($role['name']==='Super Admin'){flash('error','Super Admin always has complete access.');}else{$chosen=array_map('intval',(array)($_POST['permissions']??[]));$valid=array_map('intval',array_column($permissions,'id'));$chosen=array_values(array_intersect($chosen,$valid));$pdo=db();$pdo->beginTransaction();try{$old=$pdo->prepare('SELECT permission_id FROM admin_role_permissions WHERE role_id=?');$old->execute([$roleId]);$before=array_map('intval',array_column($old->fetchAll(),'permission_id'));$pdo->prepare('DELETE FROM admin_role_permissions WHERE role_id=?')->execute([$roleId]);$insert=$pdo->prepare('INSERT INTO admin_role_permissions(role_id,permission_id) VALUES(?,?)');foreach($chosen as $permissionId)$insert->execute([$roleId,$permissionId]);audit_log((int)admin()['id'],'ROLE_PERMISSIONS_UPDATED','admins',(string)$roleId,$before,$chosen);$pdo->commit();flash('success','Role permissions updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Could not update permissions.');}}redirect('/admin/admins/permissions.php?role_id='.$roleId);}$currentStmt=db()->prepare('SELECT permission_id FROM admin_role_permissions WHERE role_id=?');$currentStmt->execute([$roleId]);$current=array_map('intval',array_column($currentStmt->fetchAll(),'permission_id'));$pageTitle='Permissions: '.$role['name'];require APP_ROOT.'/includes/header.php';?>
<section class="panel"><form method="post"><?=csrf_field()?><div class="permission-grid"><?php foreach($permissions as $p):?><label class="check-card"><input type="checkbox" name="permissions[]" value="<?=e($p['id'])?>" <?=in_array((int)$p['id'],$current,true)?'checked':''?> <?=$role['name']==='Super Admin'?'disabled':''?>><span><strong><?=e($p['code'])?></strong><small><?=e($p['description'])?></small></span></label><?php endforeach?></div><?php if($role['name']!=='Super Admin'):?><button class="btn">Save permissions</button><?php endif?></form></section><?php require APP_ROOT.'/includes/footer.php';
